for file in html_files:
    with open(file, "r", encoding="utf-8") as f:
        content = f.read()
    
    for emoji, svg in emoji_map.items():
        content = content.replace(emoji, svg)
    
    with open(file, "w", encoding="utf-8") as f:
        f.write(content)

print("Replaced emojis in core pages!")
